import{_ as e,o as a,c as o,ai as r}from"./chunks/framework.scx6l_IK.js";const u=JSON.parse('{"title":"金刚经18分-三心不可得","description":"","frontmatter":{},"headers":[],"relativePath":"60-原文段落/金刚经18分-三心不可得.md","filePath":"60-原文段落/金刚经18分-三心不可得.md","lastUpdated":1778155802000}'),_={name:"60-原文段落/金刚经18分-三心不可得.md"};function s(n,t,p,c,d,i){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="金刚经18分-三心不可得" tabindex="-1">金刚经18分-三心不可得 <a class="header-anchor" href="#金刚经18分-三心不可得" aria-label="Permalink to &quot;金刚经18分-三心不可得&quot;">​</a></h1><blockquote><p>来源：<a href="/01-Raw-Sources/18了空居士讲《金刚经》-第十八分一体同观分20161230">18了空居士讲《金刚经》-第十八分一体同观分20161230</a> 切分日期：2026-05-06</p></blockquote><hr><p><strong>何以故？如来说诸心，皆为非心，是名为心。</strong></p><p>如来说诸心，皆为非心，是名为心，只是叫做心而已，其实都不是心是不是啊？不是这个意思！在《金刚经》里面，是什么-非什么-名什么，其实这个非什么，不是彻底否认，绝对不是，这里的非心就是&quot;不是永恒不变的心&quot;，永恒不变的心有没有？没有。所有的心念没有一个永恒不变的，永恒不变的心有没有？没有。在四念住里就有观心无常嘛！佛祖又说，大家什么心他都知道，因为他们都不是心的缘故，如果是就不知道，是不是啊？其实我们众生所有起心动念都叫做非心，也就是&quot;不是永恒不变的&quot;，都是因缘和合而生，都是六根对六尘产生六识。</p><p><strong>所以者何？须菩提！过去心不可得，现在心不可得，未来心不可得。</strong></p><p>继续解释，又在解释这个非心。世尊一环扣一环，前面就说&quot;众生若干种心如来悉知。&quot;然后给我们解释如来为什么能够知道呢？就是非心，接下来继续解释为什么我叫他非心呢，就是过去心不可得，现在心不可得，未来心不可得。过去心已成过去，现在心在不断的变化，未来的心还没有来。就是过去已去，未来未得，现在无住。佛经就是讲述这么一个道理。所以它没有一个固定不变的心，都是因缘而产生的念头。</p>',7)])])}const f=e(_,[["render",s]]);export{u as __pageData,f as default};
